<div class="section-intro"><div><p class="eyebrow">ADMINISTRATION</p><h2>Supprimer un utilisateur</h2><p class="muted">Les mouvements historiques restent conservés après la suppression d’un compte.</p></div></div><section class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">COMPTES</p><h3>Comptes supprimables</h3></div></div><div class="table-wrap"><table><thead><tr><th>Utilisateur</th><th>Email</th><th>Rôle</th><th>Action</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><strong><?= e(trim($user['prenom'] . ' ' . $user['nom'])) ?></strong><small>Créé le <?= date('d/m/Y', strtotime($user['cree_le'])) ?></small></td><td><?= e($user['email']) ?></td><td><?= e($user['role_nom']) ?></td><td><?php if ((int) $user['id'] === (int) $_SESSION['user']['id']): ?><span class="muted">Compte actuel</span><?php else: ?><form method="post" action="<?= BASE_URL ?>/index.php?page=utilisateur-delete" data-confirm="Supprimer définitivement cet utilisateur ? Les mouvements historiques seront conservés."><input type="hidden" name="id" value="<?= e($user['id']) ?>"><button class="button button-ghost danger-text" type="submit">Supprimer</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
